5: /** Exchange ticker symbol such as `COMI` or `HRHO`. Case-insensitive on input, upper-case internally. */
6: export class Ticker {
7:   private constructor(readonly value: string) {
8:     Object.freeze(this);
9:   }
10: 
11:   static of(raw: string): Ticker {
12:     const normalized = typeof raw === 'string' ? raw.trim().toUpperCase() : '';
13:     if (!TICKER_PATTERN.test(normalized)) throw new ValidationError(`Invalid ticker symbol: "${raw}"`);
14:     return new Ticker(normalized);
15:   }
16: 
17:   equals(other: Ticker): boolean {
18:     return other.value === this.value;
19:   }
20: 
21:   toString(): string {
22:     return this.value;
23:   }
24: 
25:   toJSON(): string {
26:     return this.value;
27:   }
28: }

